css:
.ct-doc { font-family: Arial, "Noto Sans Arabic", sans-serif; font-size: 10px; color: #1f2933; }
.ct-head { border-bottom: 2px solid #1f2933; padding-bottom: 8px; margin-bottom: 12px; }
.ct-org { font-size: 16px; font-weight: bold; text-align: center; }
.ct-title { font-size: 13px; text-align: center; margin-top: 2px; color: #3e4c59; }
.ct-meta { width: 100%; border-collapse: collapse; margin-top: 10px; }
.ct-meta th, .ct-meta td { border: 1px solid #d9e2ec; padding: 4px 6px; text-align: left; vertical-align: top; }
.ct-meta th { background-color: #f0f4f8; width: 18%; font-weight: bold; }
.ct-items { width: 100%; border-collapse: collapse; margin-top: 12px; }
.ct-items th { background-color: #1f2933; color: #ffffff; padding: 5px 6px; border: 1px solid #1f2933; font-size: 9px; text-align: left; }
.ct-items td { border: 1px solid #d9e2ec; padding: 4px 6px; }
.ct-items tfoot td { background-color: #f0f4f8; font-weight: bold; }
.ct-items tr.ct-total td { background-color: #1f2933; color: #ffffff; font-weight: bold; }
.ct-num { text-align: right; }
.ct-label { text-align: left; }
.ct-sign { display: flex; justify-content: space-between; margin-top: 40px; }
.ct-sign div { width: 40%; border-top: 1px solid #1f2933; padding-top: 4px; text-align: center; }
